/*
 * OOPS chapter for the Code walkthrough (Explore the Platform → /guide).
 *
 * Self-contained add-on: it does not change any existing function, style or chapter. When the walkthrough
 * is on screen it appends one "OOPS" entry to the Chapters sidebar and the chapter cards, plus one chapter
 * article at the end of the main column, and reuses the page's own chapter styles, code-table styles,
 * syntax highlighter (highlightLines) and jump action (data-act="guide-jump").
 *
 * The concept index and every line of code come from oops/data/oops-index.js, generated by
 * oops/tools/build-index.mjs from the real DigiVote repository. Nothing here is source code shown to the
 * reader; explanations are labelled as written for this guide.
 */
(() => {
  'use strict';
  if (window.__digivoteOops) return;
  window.__digivoteOops = true;

  const CHAPTER_ID = 'ch-oops';
  const BASE = (document.currentScript && document.currentScript.src) || location.href;
  const DATA_URL = new URL('data/oops-index.js', BASE).href;
  const LANG = { java: 'Java', js: 'JavaScript' };
  const STATUS = { found: '', indirect: 'Indirect', absent: 'Not found' };

  const st = {
    data: null, status: 'idle', error: '', q: '', lang: 'all',
    id: null, ref: 0, whole: false, open: null, focus: null, verified: {}, pendingScroll: false,
  };

  const h = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const base = (p) => p.split('/').pop();
  const langOf = (r) => (r.file.endsWith('.jsx') ? 'JSX' : LANG[r.lang] || r.lang);
  const concept = () => st.data && st.data.concepts.find((c) => c.id === st.id);

  // ----------------------------------------------------------------------------------------- styles
  const CSS = `
.oops-x { display:flex; flex-direction:column; gap:14px; }
.oops-bar { display:flex; flex-wrap:wrap; gap:10px 16px; align-items:center; justify-content:space-between; border:1px solid rgba(80,120,255,.22); border-radius:12px; padding:10px 14px; background:linear-gradient(180deg,rgba(20,34,86,.55),rgba(8,14,40,.78)); color:#cbd5e1; font-size:13px; }
.oops-bar b { color:#fff; }
.oops-src { font:12px var(--mono); color:#93a4c8; word-break:break-all; }
.oops-grid { display:grid; gap:14px; grid-template-columns:minmax(0,1fr); }
@media (min-width:900px) { .oops-grid { grid-template-columns:15rem minmax(0,1fr); } .oops-side { grid-column:1 / -1; } }
@media (min-width:1400px) { .oops-grid { grid-template-columns:15rem minmax(0,1fr) 21rem; } .oops-side { grid-column:auto; } }
.oops-panel { border:1px solid #1e2b4f; border-radius:12px; background:#0b1530; color:#dbe4f3; min-width:0; }
.oops-list { padding:10px; display:flex; flex-direction:column; gap:8px; max-height:760px; overflow:auto; }
@media (max-width:899px) { .oops-list { max-height:340px; } }
@media (min-width:900px) { .oops-list { position:sticky; top:84px; } }
.oops-list input { width:100%; box-sizing:border-box; border:1px solid #2a3a66; background:#0e1a3a; color:#e2e8f0; border-radius:8px; padding:7px 10px; font:13px var(--font); }
.oops-list input:focus { outline:2px solid #3b82f6; outline-offset:1px; }
.oops-langs { display:flex; gap:4px; flex-wrap:wrap; }
.oops-langs button { border:1px solid #2a3a66; background:none; color:#a5b4d4; border-radius:999px; padding:2px 10px; font-size:12px; cursor:pointer; }
.oops-langs button[aria-pressed="true"] { background:#3b82f6; border-color:#3b82f6; color:#fff; }
.oops-g { font-size:11px; font-weight:600; letter-spacing:.08em; text-transform:uppercase; color:#60a5fa; padding:8px 6px 2px; }
.oops-item { display:flex; gap:6px; align-items:baseline; width:100%; text-align:left; border:0; background:none; color:#cbd5e1; padding:6px 8px; border-radius:6px; cursor:pointer; font-size:13.5px; line-height:1.35; }
.oops-item:hover { background:rgba(59,130,246,.12); color:#fff; }
.oops-item[aria-current="true"] { background:rgba(59,130,246,.22); color:#fff; box-shadow:inset 3px 0 0 #3b82f6; }
.oops-item small { margin-left:auto; color:#64748b; font:11px var(--mono); flex-shrink:0; }
.oops-item.absent { color:#7d8bab; }
.oops-empty { color:#93a4c8; font-size:13px; padding:10px 8px; }
.oops-head { padding:14px 16px; border-bottom:1px solid #1e2b4f; display:flex; flex-direction:column; gap:8px; }
.oops-head h3 { margin:0; font-size:19px; color:#fff; }
.oops-meta { display:flex; flex-wrap:wrap; gap:6px 12px; align-items:center; font-size:12.5px; color:#a5b4d4; }
.oops-meta .mono { font:12px var(--mono); color:#dbe4f3; word-break:break-all; }
.oops-tag { font:700 10.5px var(--mono); letter-spacing:.06em; text-transform:uppercase; border-radius:4px; padding:2px 7px; background:#64748b33; color:#cbd5e1; }
.oops-tag.ind { background:#f59e0b22; color:#fbbf24; } .oops-tag.abs { background:#ef444422; color:#fca5a5; } .oops-tag.ok { background:#22c55e22; color:#86efac; }
.oops-tabs { display:flex; gap:4px; flex-wrap:wrap; padding:8px 12px 0; border-bottom:1px solid #1e2b4f; }
.oops-tabs button { border:1px solid #1e2b4f; border-bottom:0; background:#0e1a3a; color:#a5b4d4; border-radius:8px 8px 0 0; padding:6px 10px; font-size:12.5px; cursor:pointer; max-width:100%; text-align:left; }
.oops-tabs button[aria-selected="true"] { background:#101d40; color:#fff; box-shadow:inset 0 2px 0 #3b82f6; }
.oops-tabs button span { display:block; font-size:11px; color:#7d8bab; }
.oops-code-h { display:flex; flex-wrap:wrap; justify-content:space-between; gap:6px 12px; padding:8px 14px; background:#101d40; border-bottom:1px solid #1e2b4f; font-size:12.5px; color:#a5b4d4; }
.oops-code-h > span { min-width:0; } .oops-code-h .mono { font:12px var(--mono); color:#dbe4f3; word-break:break-all; }
.oops-code-h button { border:1px solid #334155; background:transparent; color:#cbd5e1; border-radius:5px; padding:2px 9px; font-size:12px; cursor:pointer; }
.oops-code-h button:hover { background:#1e293b; }
.oops-x .code tr.hl { cursor:pointer; }
.oops-x .code tr.ctx td { opacity:.55; }
.oops-label { font-size:11px; font-weight:600; letter-spacing:.08em; text-transform:uppercase; color:#60a5fa; margin:0 0 6px; }
.oops-side { padding:14px; display:flex; flex-direction:column; gap:16px; font-size:13.5px; line-height:1.6; }
.oops-side p { margin:0; color:#cbd5e1; }
.oops-notes { list-style:none; margin:0; padding:0; display:flex; flex-direction:column; gap:6px; }
.oops-note { display:flex; gap:8px; width:100%; text-align:left; border:1px solid #1e2b4f; background:#0e1a3a; color:#dbe4f3; border-radius:8px; padding:8px 10px; cursor:pointer; font-size:13px; line-height:1.5; }
.oops-note:hover { border-color:#3b82f6; }
.oops-note.on { border-color:#facc15; background:rgba(250,204,21,.08); }
.oops-note i { display:block; font-style:normal; font:11px var(--mono); color:#7d8bab; margin-top:2px; }
.oops-refs { list-style:none; margin:0; padding:0; display:flex; flex-direction:column; gap:4px; max-height:260px; overflow:auto; }
.oops-refs li { font-size:12.5px; }
.oops-refs button, .oops-refs span.r { display:block; width:100%; text-align:left; border:0; background:none; color:#cbd5e1; padding:4px 6px; border-radius:5px; font:12px var(--mono); word-break:break-all; }
.oops-refs button { cursor:pointer; } .oops-refs button:hover { background:rgba(59,130,246,.12); color:#fff; }
.oops-refs em { font-style:normal; color:#60a5fa; font-family:var(--font); margin-right:6px; }
.oops-viva { border:1px solid #1e2b4f; border-radius:8px; padding:8px 10px; background:#0e1a3a; }
.oops-viva summary { cursor:pointer; color:#fff; font-weight:600; }
.oops-viva p { margin-top:6px; }
.oops-state { padding:28px 18px; text-align:center; color:#cbd5e1; display:flex; flex-direction:column; gap:10px; align-items:center; }
.oops-state button { border:1px solid #3b82f6; background:#3b82f6; color:#fff; border-radius:8px; padding:6px 14px; cursor:pointer; }
.oops-absent { margin:16px; border:1px dashed #475569; border-radius:10px; padding:14px 16px; color:#cbd5e1; }
.oops-absent b { color:#fca5a5; }
.oops-legend { font-size:12px; color:#7d8bab; }
`;

  function ensureStyle() {
    if (document.getElementById('oops-style')) return;
    const s = document.createElement('style');
    s.id = 'oops-style';
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  // -------------------------------------------------------------------------------------- data load
  function load(retry) {
    if (st.status === 'loading' || st.status === 'ready') return;
    st.status = 'loading';
    render();
    document.getElementById('oops-data')?.remove();
    delete window.DIGIVOTE_OOPS_INDEX;
    const s = document.createElement('script');
    s.id = 'oops-data';
    s.src = DATA_URL + (retry ? `?r=${Date.now()}` : '');
    s.onload = () => {
      const d = window.DIGIVOTE_OOPS_INDEX;
      if (!d || !Array.isArray(d.concepts)) { st.status = 'error'; st.error = 'The concept index loaded but is not in the expected format.'; }
      else {
        st.data = d; st.status = 'ready';
        const wanted = new URLSearchParams((location.hash.split('?')[1]) || '').get('oops');
        st.id = d.concepts.some((c) => c.id === wanted) ? wanted : (st.id || d.concepts[0]?.id);
        verifyFiles();
      }
      render();
      scrollIfLinked();
    };
    s.onerror = () => {
      st.status = 'error';
      st.error = `Could not load the concept index from ${DATA_URL.replace(/\?.*$/, '')}. Regenerate it with node oops/tools/build-index.mjs and serve this folder.`;
      render();
    };
    document.head.appendChild(s);
  }

  // Re-hash each copied file in the browser so a damaged or hand-edited copy is flagged, not shown as real.
  async function verifyFiles() {
    if (!(window.crypto && crypto.subtle)) return;
    for (const [path, f] of Object.entries(st.data.files)) {
      try {
        const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(f.lines.join('\n')));
        const hex = Array.from(new Uint8Array(buf), (b) => b.toString(16).padStart(2, '0')).join('');
        st.verified[path] = hex === f.sha256;
      } catch { /* leave unverified */ }
    }
    render();
  }

  // ----------------------------------------------------------------------------------- highlighting
  function highlighted(lines, lang) {
    const code = lines.join('\n');
    try {
      if (typeof highlightLines === 'function') return highlightLines(code, lang === 'js' ? 'js' : 'java');
    } catch { /* fall through */ }
    return lines.map(h);
  }

  // --------------------------------------------------------------------------------------- markup
  function listHtml() {
    const d = st.data;
    const q = st.q.trim().toLowerCase();
    const match = (c) => (st.lang === 'all' || c.languages.includes(st.lang) || (st.lang === 'absent' && c.status === 'absent'))
      && (!q || [c.name, c.definition, c.group, ...c.refs.map((r) => r.file + ' ' + r.symbol)].join(' ').toLowerCase().includes(q));
    const shown = d.concepts.filter(match);
    if (!shown.length) return `<p class="oops-empty">No concept matches “${h(st.q)}”.</p>`;
    return d.groups.map((g) => {
      const items = shown.filter((c) => c.group === g);
      if (!items.length) return '';
      return `<div class="oops-g">${h(g)}</div>${items.map((c) => `<button type="button" class="oops-item${c.status === 'absent' ? ' absent' : ''}" data-oops="pick" data-id="${h(c.id)}" aria-current="${c.id === st.id}">${h(c.name)}<small>${c.status === 'absent' ? '—' : c.refs.length}</small></button>`).join('')}`;
    }).join('');
  }

  function codeHtml(c, r) {
    const f = st.data.files[r.file];
    if (!f) return `<div class="oops-absent"><b>Source missing.</b> ${h(r.file)} is not in the index. Regenerate it with node oops/tools/build-index.mjs.</div>`;
    const marks = new Map(r.marks.map((m, i) => [m.line, i + 1]));
    const from = st.whole ? 1 : r.start;
    const to = st.whole ? f.lines.length : r.end;
    const lines = f.lines.slice(from - 1, to);
    const html = highlighted(lines, r.lang);
    const rows = lines.map((_, i) => {
      const ln = from + i;
      const n = marks.get(ln);
      const outside = st.whole && (ln < r.start || ln > r.end);
      return `<tr class="${n ? 'hl' : ''}${outside ? ' ctx' : ''}${st.focus === ln ? ' focus' : ''}" data-line="${ln}"${n ? ` data-oops="line" data-n="${n}"` : ''}><td class="ln">${ln}</td><td class="mk">${n ? `<span class="bub">${n}</span>` : ''}</td><td class="cl">${html[i] || ' '}</td></tr>`;
    }).join('');
    const ok = st.verified[r.file];
    return `<div class="oops-code-h"><span><span class="lang lang-${r.lang === 'js' ? 'js' : 'java'}">${h(langOf(r))}</span> <span class="mono">${h(r.file)}</span> · lines ${r.start}–${r.end}${ok === false ? ' · <b style="color:#fca5a5">copy does not match its recorded hash</b>' : ''}</span>
      <span><button type="button" data-oops="whole">${st.whole ? 'Show excerpt only' : 'Show whole file'}</button> <button type="button" data-oops="copy">Copy</button></span></div>
      <div class="code" id="oops-code" tabindex="0" aria-label="Source of ${h(r.file)}"><table><tbody>${rows}</tbody></table></div>`;
  }

  function openFileHtml() {
    const { file, line } = st.open;
    const f = st.data.files[file];
    const from = Math.max(1, line - 12), to = Math.min(f.lines.length, line + 12);
    const html = highlighted(f.lines.slice(from - 1, to), file.endsWith('.java') ? 'java' : 'js');
    const rows = html.map((x, i) => `<tr class="${from + i === line ? 'hl focus' : ''}"><td class="ln">${from + i}</td><td class="mk"></td><td class="cl">${x || ' '}</td></tr>`).join('');
    return `<div class="oops-code-h"><span><span class="lang lang-${file.endsWith('.java') ? 'java' : 'js'}">${file.endsWith('.java') ? 'Java' : 'JavaScript'}</span> <span class="mono">${h(file)}</span> · around line ${line}</span>
      <span><button type="button" data-oops="close-open">← Back to ${h(concept().name)}</button></span></div>
      <div class="code" tabindex="0"><table><tbody>${rows}</tbody></table></div>`;
  }

  function xrefHtml(r) {
    const x = st.data.xref[r.file];
    if (!x) return '<p>No cross-references recorded for this file.</p>';
    if (!x.hits.length) return `<p>No other source file mentions ${h(x.name)}.</p>`;
    return `<ul class="oops-refs">${x.hits.map((t) => {
      const label = `<em>${h(t.kind)}</em>${h(t.file.replace(/^backend\/src\/main\/java\/com\/digivote\//, '').replace(/^frontend\/src\//, 'frontend/'))}:${t.line}`;
      return `<li>${st.data.files[t.file] ? `<button type="button" data-oops="open" data-file="${h(t.file)}" data-line="${t.line}" title="${h(t.text)}">${label}</button>` : `<span class="r" title="${h(t.text)}">${label}</span>`}</li>`;
    }).join('')}</ul><p class="oops-legend">${x.hits.length} mention(s) of ${h(x.name)} found by scanning ${st.data.meta.scannedFiles} source files. Entries you can click are included in this guide; hover the others to see the line.</p>`;
  }

  function sideHtml(c, r) {
    if (c.status === 'absent') {
      return `<div><p class="oops-label">Definition (written for this guide)</p><p>${h(c.definition)}</p></div>`;
    }
    const notes = r.marks.map((m, i) => `<li><button type="button" class="oops-note${st.focus === m.line ? ' on' : ''}" data-oops="note" data-line="${m.line}" id="oops-note-${i + 1}"><span class="bub">${i + 1}</span><span>${h(m.note)}<i>line ${m.line}</i></span></button></li>`).join('');
    return `<div><p class="oops-label">Definition</p><p>${h(c.definition)}</p></div>
      <div><p class="oops-label">Highlighted lines · ${h(base(r.file))}</p><ol class="oops-notes">${notes || '<li class="oops-empty">No highlighted lines.</li>'}</ol></div>
      <div><p class="oops-label">Why DigiVote uses it</p><p>${h(c.why)}</p></div>
      <div><p class="oops-label">How it fits the workflow</p><p>${h(c.workflow)}</p></div>
      <div><p class="oops-label">Where ${h(st.data.xref[r.file]?.name || base(r.file))} is referenced</p>${xrefHtml(r)}</div>
      ${c.viva ? `<details class="oops-viva"><summary>Viva: ${h(c.viva.q)}</summary><p>${h(c.viva.a)}</p></details>` : ''}
      <p class="oops-legend">Code is copied verbatim from the repository. Definitions, notes and answers are explanations written for this guide.</p>`;
  }

  function mainHtml() {
    const c = concept();
    if (!c) return '<div class="oops-state">Pick a concept on the left.</div>';
    const tag = c.status === 'absent' ? '<span class="oops-tag abs">Not found in DigiVote</span>' : c.status === 'indirect' ? '<span class="oops-tag ind">Indirect relationship</span>' : '<span class="oops-tag ok">Found in DigiVote</span>';
    if (c.status === 'absent') {
      return `<div class="oops-head"><div class="oops-meta">${tag}<span>${h(c.group)}</span></div><h3>${h(c.name)}</h3></div>
        <div class="oops-absent"><b>No direct implementation found in the current DigiVote codebase.</b><p style="margin-top:6px">${h(c.absent.replace(/^No direct implementation found in the current DigiVote codebase\.\s*/, ''))}</p></div>`;
    }
    const r = c.refs[st.ref] || c.refs[0];
    const langs = [...new Set(c.refs.map(langOf))].map((l) => `<span class="lang lang-${l === 'Java' ? 'java' : 'js'}">${h(l)}</span>`).join(' ');
    const tabs = c.refs.map((x, i) => `<button type="button" role="tab" aria-selected="${i === st.ref && !st.open}" data-oops="ref" data-i="${i}">${i + 1}. ${h(base(x.file))}<span>${h(x.role)}</span></button>`).join('');
    return `<div class="oops-head"><div class="oops-meta">${tag}${langs}<span>${h(c.group)}</span></div><h3>${h(c.name)}</h3>
      <div class="oops-meta"><span class="mono">${h(r.symbol)}</span><span>${h(r.role)}</span></div></div>
      <div class="oops-tabs" role="tablist" aria-label="Related code">${tabs}</div>
      ${st.open ? openFileHtml() : codeHtml(c, r)}`;
  }

  function explorerHtml() {
    if (st.status !== 'ready') {
      if (st.status === 'error') return `<div class="oops-panel oops-state" role="alert"><b>The OOPS index could not be loaded.</b><span>${h(st.error)}</span><button type="button" data-oops="retry">Retry</button></div>`;
      return `<div class="oops-panel oops-state" aria-busy="true">Loading the concept index…</div>`;
    }
    const d = st.data, m = d.meta, c = concept();
    const found = d.concepts.filter((x) => x.status !== 'absent').length;
    const excerpts = d.concepts.reduce((n, x) => n + x.refs.length, 0);
    const langBtn = (k, l) => `<button type="button" data-oops="lang" data-lang="${k}" aria-pressed="${st.lang === k}">${l}</button>`;
    const r = c && c.refs[st.ref];
    return `<div class="oops-bar"><span><b>${found}</b> concepts found · <b>${d.concepts.length - found}</b> not found · <b>${excerpts}</b> excerpts from <b>${Object.keys(d.files).length}</b> files</span>
      <span class="oops-src">${h(m.sourceRepository)} @ ${h(m.commitShort)} · indexed ${h((m.generatedAt || '').slice(0, 10))}${m.uncommittedFiles.length ? ` · uncommitted: ${h(m.uncommittedFiles.join(', '))}` : ''}</span></div>
      <div class="oops-grid">
        <nav class="oops-panel oops-list" aria-label="OOPS concepts">
          <input type="search" id="oops-q" placeholder="Search concepts, classes, files" value="${h(st.q)}" aria-label="Search OOPS concepts">
          <div class="oops-langs">${langBtn('all', 'All')}${langBtn('java', 'Java')}${langBtn('js', 'JavaScript')}${langBtn('absent', 'Not found')}</div>
          <div id="oops-items">${listHtml()}</div>
        </nav>
        <section class="oops-panel" aria-live="polite">${mainHtml()}</section>
        <aside class="oops-panel oops-side" id="oops-side">${c ? sideHtml(c, r) : ''}</aside>
      </div>`;
  }

  function articleHtml(n, prev) {
    return `<header class="chap-head"><span class="chap-num">${String(n).padStart(2, '0')}</span><div style="min-width:0"><p class="chap-eye">Chapter ${n}</p><h2>OOPS</h2><p class="chap-tag">Every object-oriented concept found in DigiVote's real source, with the exact lines that show it.</p></div></header>
      <div class="why"><b>How to read this chapter</b><p>Pick a concept on the left. The centre shows the real file and line numbers; numbered markers point at the lines that demonstrate the concept, and the panel on the right explains each one. Tabs above the code open the related classes and call sites. Concepts DigiVote does not use are listed honestly under “Not found in DigiVote”.</p></div>
      <div id="oops-explorer" class="oops-x">${explorerHtml()}</div>
      <div class="chap-foot"><span></span><span class="row">${prev ? `<button type="button" class="btn ghost sm" data-act="guide-jump" data-id="${h(prev.id)}">← ${h(prev.title)}</button>` : ''}</span></div>`;
  }

  // ------------------------------------------------------------------------------------ rendering
  function render() {
    const mount = document.getElementById('oops-explorer');
    if (!mount) return;
    const side = document.getElementById('oops-side');
    const sideScroll = side ? side.scrollTop : 0;
    const active = document.activeElement && document.activeElement.id === 'oops-q';
    mount.innerHTML = explorerHtml();
    const ns = document.getElementById('oops-side');
    if (ns) ns.scrollTop = sideScroll;
    if (active) { const q = document.getElementById('oops-q'); q.focus(); q.setSelectionRange(q.value.length, q.value.length); }
  }

  // Adds the chapter whenever the walkthrough is (re)drawn by the page's own router.
  function inject() {
    const nav = document.querySelector('.wt-nav ol');
    const main = document.querySelector('.wt-main');
    if (!nav || !main || document.getElementById(CHAPTER_ID)) return;
    ensureStyle();
    const n = nav.children.length + 1;
    const lastBtn = nav.lastElementChild && nav.lastElementChild.querySelector('button');
    const prev = lastBtn ? { id: lastBtn.dataset.id, title: lastBtn.textContent.replace(/^\d+/, '') } : null;

    const li = document.createElement('li');
    li.dataset.oopsChapter = '';
    li.innerHTML = `<button type="button" data-act="guide-jump" data-id="${CHAPTER_ID}"><span>${String(n).padStart(2, '0')}</span>OOPS</button>`;
    nav.appendChild(li);

    const toc = document.querySelector('.toc-grid');
    if (toc) {
      const card = document.createElement('button');
      card.type = 'button';
      card.className = 'toc-card';
      card.dataset.act = 'guide-jump';
      card.dataset.id = CHAPTER_ID;
      card.innerHTML = `<span class="toc-n">${String(n).padStart(2, '0')}</span><span class="toc-b"><b>OOPS</b><span>Object-oriented concepts in the real DigiVote code.</span></span>`;
      toc.appendChild(card);
    }

    const art = document.createElement('article');
    art.className = 'chap';
    art.id = CHAPTER_ID;
    art.innerHTML = articleHtml(n, prev);
    main.appendChild(art);

    if (st.status === 'idle' || st.status === 'error') load(st.status === 'error');
    if (new URLSearchParams((location.hash.split('?')[1]) || '').has('oops')) st.pendingScroll = true;
    scrollIfLinked();
  }

  // A link such as #/guide?oops=generics opens the chapter at that concept once the page has settled.
  function scrollIfLinked() {
    if (!st.pendingScroll || st.status === 'loading') return;
    st.pendingScroll = false;
    setTimeout(() => document.getElementById(CHAPTER_ID)?.scrollIntoView({ block: 'start' }), 120);
  }

  function select(id) {
    st.id = id; st.ref = 0; st.whole = false; st.open = null; st.focus = null;
    try { history.replaceState(null, '', `#/guide?oops=${encodeURIComponent(id)}`); } catch { /* sandboxed */ }
    render();
  }

  function focusLine(line, fromCode) {
    st.focus = line;
    render();
    const row = document.querySelector(`#oops-code tr[data-line="${line}"]`);
    const box = document.getElementById('oops-code');
    if (row && box) box.scrollTo({ top: row.offsetTop - box.clientHeight / 3, behavior: 'smooth' });
    if (fromCode) document.querySelector('.oops-note.on')?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }

  // ------------------------------------------------------------------------------------- events
  document.addEventListener('click', (ev) => {
    const el = ev.target.closest('[data-oops]');
    if (!el || !el.closest('#oops-explorer')) return;
    const c = concept();
    switch (el.dataset.oops) {
      case 'pick': select(el.dataset.id); break;
      case 'lang': st.lang = el.dataset.lang; render(); break;
      case 'ref': st.ref = Number(el.dataset.i); st.open = null; st.focus = null; render(); break;
      case 'whole': st.whole = !st.whole; render(); break;
      case 'note': focusLine(Number(el.dataset.line), false); break;
      case 'line': focusLine(Number(el.closest('tr').dataset.line), true); break;
      case 'open': st.open = { file: el.dataset.file, line: Number(el.dataset.line) }; render(); break;
      case 'close-open': st.open = null; render(); break;
      case 'retry': st.status = 'error'; load(true); break;
      case 'copy': {
        const r = c.refs[st.ref];
        const f = st.data.files[r.file];
        const text = (st.whole ? f.lines : f.lines.slice(r.start - 1, r.end)).join('\n');
        const done = (msg) => { el.textContent = msg; setTimeout(() => { el.textContent = 'Copy'; }, 1500); };
        navigator.clipboard?.writeText(text).then(() => done('Copied'), () => done('Copy blocked')) ?? done('Copy blocked');
        break;
      }
      default: break;
    }
  });

  document.addEventListener('input', (ev) => {
    if (ev.target.id !== 'oops-q') return;
    st.q = ev.target.value;
    const box = document.getElementById('oops-items');
    if (box) box.innerHTML = listHtml();
  });

  // The page redraws #root on every navigation; re-add the chapter each time the walkthrough appears.
  const root = document.getElementById('root') || document.body;
  new MutationObserver(inject).observe(root, { childList: true });
  inject();
})();
